-- Commercials: each scene's spoken line, generated by the film engine's
-- text-to-speech in the speaking character's voice, stored as a VOICE asset
-- and mixed in at the scene's start when the ad is mastered.
ALTER TABLE studio_assets DROP CONSTRAINT IF EXISTS studio_assets_role_check;
ALTER TABLE studio_assets ADD CONSTRAINT studio_assets_role_check CHECK (role IN ('PHOTO', 'MUSIC', 'VIDEO', 'SFX', 'MIX', 'VOICE'));
ALTER TABLE studio_scenes ADD COLUMN IF NOT EXISTS voice_asset_id uuid REFERENCES studio_assets(id) ON DELETE SET NULL;
